    # -------------------------------------------------------------- evidence
    def _read_evidence(
        self,
        context: Mapping[str, Any],
        params: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        """Return the evidence mapping ``{"images", "references", "frames", ...}``.

        ``context["collected_state"]`` (collector snapshot) takes precedence over
        a live guest read; see the module docstring for its documented shape.
        """
        collected = context.get("collected_state")
        if collected is not None:
            if not isinstance(collected, Mapping):
                raise TypeError("collected_state must be a mapping")
            return self._evidence_from_collected(collected, params)
        controller = context.get("controller")
        if controller is None or not hasattr(controller, "run_python_script"):
            raise RuntimeError("controller.run_python_script is required")
        return self._read_evidence_from_guest(controller, params)

    def _evidence_from_collected(
        self,
        collected: Mapping[str, Any],
        params: Mapping[str, Any],
    ) -> dict[str, Any]:
        images = collected.get("images")
        images = dict(images) if isinstance(images, Mapping) else {}
        evidence: dict[str, Any] = {
            "source": "collected_state",
            "images": images,
            "fixtures": collected.get("fixtures"),
            "references": {},
            "frames": {},
            "reference_missing": [],
        }
        self._augment_evidence(evidence, params)
        return evidence

    def _read_evidence_from_guest(
        self,
        controller: Any,
        params: Mapping[str, Any],
    ) -> dict[str, Any]:
        payload = self._guest_payload(params)
        script = _guest_script(payload)
        timeout = self._as_int(params.get("timeout")) or 90
        result = controller.run_python_script(script, timeout=timeout)
        returncode = int(result.get("returncode", -1))
        output = str(result.get("stdout") or result.get("output") or "").strip()
        error = str(result.get("stderr") or result.get("error") or "").strip()
        if not output:
            raise RuntimeError(error or f"guest evidence script exited {returncode} without output")
        # Same convention as the shipped family bases: ONE json line, last line wins.
        evidence = json.loads(output.splitlines()[-1])
        if not isinstance(evidence, Mapping):
            raise TypeError(f"guest evidence payload is not an object: {evidence!r}")
        evidence = dict(evidence)
        if evidence.get("error"):
            raise RuntimeError(f"guest evidence script reported {evidence['error']}")
        if not isinstance(evidence.get("images"), Mapping):
            raise TypeError("guest evidence payload has no 'images' object")
        evidence["source"] = "guest"
        self._augment_evidence(evidence, params)
        return evidence

    def _augment_evidence(
        self,
        evidence: dict[str, Any],
        params: Mapping[str, Any],
    ) -> None:
        """Normalise collector/guest bookkeeping the checks rely on."""
        for key in ("references", "frames"):
            if not isinstance(evidence.get(key), Mapping):
                evidence[key] = {}
        if not isinstance(evidence.get("reference_missing"), list):
            evidence["reference_missing"] = []
        if evidence.get("marker_box") is None:
            evidence["marker_box"] = self._marker_box(params, evidence)
        if evidence.get("marker_grid") is None:
            evidence["marker_grid"] = self._marker_grid(params, evidence)
        evidence["reference_file"] = self._manifest_reference_file(evidence)

